package com.xenris.liquidwarsos.cloud;
import org.json.*;
import java.net.URLEncoder;

/** Numeric world observations and direct simultaneous touch targets. */
public final class ModelProtocol {
    public static final String RULES="You command YOUR team only. Choose tactics yourself: no local AI, auto-pursuit or rescue. Coordinates use STATIC_NAVIGATION.world dimensions, bottom-left; all observations are facts, not recommendations.\nPREPARING=true means the start countdown freezes ALL armies. No movement is expected yet; preserve your first valid plan.\nMOVEMENT: each particle moves toward its NEAREST simultaneous touch, at ideal140px/s, no global pathfinder. A blocked particle only side-steps. Select ordered adjacent door IDs from your current room; host follows ONLY your selected doors. to must be floor visible from the FINAL door (or current mass for route[]). Region borders themselves are NOT walls. Use route[] for clear direct travel/open maps. One touch during travel; extra points are simultaneous close FINAL pincer points, never waypoints.\nCLOAK: hidden_enemy_ids are temporarily invisible, NOT eliminated. Their current locations and troops are omitted; do not track them. Death immediately eliminates an unprotected selected enemy. Every timed effect lasts20s; ceasefire never shares victory, rewind appears once. Powers and counters spawn together. COMBAT: damage only when a particle attempts to push into an enemy in its touch direction. Merely standing beside an enemy is insufficient. Friendly blocked pushes may heal; allies cannot hurt/convert each other. Damage3/4, maxhealth10, new/capturedhealth5. intent=stop gives(-2,-2): immobile, NO attacks/counterattacks or initiated healing, vulnerable. hold requires an ACTIVE point beyond the doorway/front, not your own center.\nDECISION PRIORITY:\n1 Survive. Read count_change, hostile contacts and troops_within64_of_your_mass_by_team. Sustained losses or multiple attackers require a NEW defensive action: choose a safe exit/retreat route or an active door hold. Do not keep repeating an attack while your army shrinks. Retreating through enemies is unsafe.\n2 Compare opponents by strength, walking distance, third-party fighting, fragmentation and route traffic. Avoid idle enemies>1.5x you. Nearest is not automatically best. A target you cannot reach safely may be abandoned.\n3 Choose route. direct_clear=false means use door IDs, never push straight through walls. Compare alternative doors for flanking an engaged army. routes_by_length are geometric candidates only. Respect legal_doors and progress; repeated identical nonempty route retains progress.\n4 Timing: force advantage can attack; equal/weak can actively hold a choke/regroup while others fight. Leading favors survival; trailing near timeout favors initiative. At contact choose a touch ACROSS the enemy front so particles attack, with nearby pincer points only if you can keep the whole front active.\n5 Keep a coherent target/plan until invalid or materially changed. Read previous_command and last_feedback. If rejected, fix the actual offending field/door/visibility. Same repeated invalid command does nothing. With allies focus jointly and leave lanes open.\nReturn ONLY JSON {\"enemy\":2,\"intent\":\"flank\",\"route\":[3,7],\"to\":[x,y],\"plan\":\"flank north\",\"hold_ms\":6000}. enemy living hostile0..5 or-1; intent attack/flank/retreat/hold/regroup/stop; route<=64 adjacent doors; integer to within the world bounds in STATIC_NAVIGATION.world. plan<=40characters, prefer2-4short words; no explanations. Optional points<=4extra final pairs. Stop: route:[],points:[], omit to. Routed hold_ms100..6000, normally6000; legacy direct points<=2000. New replies replace current command; expiry/network failure stops. Replies older5000ms rejected. No prose or hidden reasoning.";

    // SimpleTool's parallel heads are POSITIONAL. Preserve property order in this literal;
    // JSONObject does not promise insertion order across Android and desktop implementations.
    private static final String SIMPLE_TOOLS="[{\"type\":\"function\",\"function\":{\"name\":\"move_points\",\"description\":\"Set five simultaneous attraction points; unused slots are a dash.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"p1\":{\"type\":\"string\",\"description\":\"x,y or -\"},\"p2\":{\"type\":\"string\",\"description\":\"x,y or -\"},\"p3\":{\"type\":\"string\",\"description\":\"x,y or -\"},\"p4\":{\"type\":\"string\",\"description\":\"x,y or -\"},\"p5\":{\"type\":\"string\",\"description\":\"x,y or -\"},\"hold_ms\":{\"type\":\"integer\",\"minimum\":100,\"maximum\":2000}},\"required\":[\"p1\",\"p2\",\"p3\",\"p4\",\"p5\",\"hold_ms\"]}}}]";
    public static String observation(int team,int[] state,int[] previous,long dt,int[] alliances,short[] current,long frame)throws Exception{
        if(!ModelWorld.valid(state))throw new IllegalArgumentException("Snapshot dimensions");JSONArray teams=new JSONArray();
        for(int p=0;p<6;p++){
            int at=p*8;JSONArray clusters=new JSONArray();for(int k=0;k<4;k++){int offset=48+p*12+k*3;if(state[offset+2]>0)clusters.put(new JSONArray().put(state[offset]).put(state[offset+1]).put(state[offset+2]));}
            JSONObject item=new JSONObject().put("id",p).put("relation",p==team?"YOU":alliances[p]==alliances[team]?"ALLY":"ENEMY").put("count",state[at]).put("hp_percent",state[at+1]).put("center",new JSONArray().put(state[at+2]).put(state[at+3])).put("main_mass",new JSONArray().put(state[at+4]).put(state[at+5])).put("groups_x_y_count",clusters).put("hostiles_within48",state[at+7]);
            if(previous!=null&&dt>0){item.put("count_change",state[at]-previous[at]);item.put("velocity_px_sec",new JSONArray().put((state[at+2]-previous[at+2])*1000/dt).put((state[at+3]-previous[at+3])*1000/dt));}
            teams.put(item);
        }
        JSONArray fingers=new JSONArray();for(int i=0;i<5;i++)if(current[i]>=0)fingers.put(new JSONArray().put(current[i]).put(current[i+5]));
        JSONArray enemies=new JSONArray(),allies=new JSONArray();JSONObject self=null;
        for(int p=0;p<6;p++){JSONObject item=teams.getJSONObject(p);if(p==team)self=item;else if(alliances[p]==alliances[team])allies.put(item);else if(state[p*8]>0)enemies.put(item);}
        return new JSONObject().put("frame",frame).put("delta_ms",dt).put("YOU",self).put("ENEMIES",enemies).put("ALLIES",allies).put("last_destination",fingers).toString();

    }
    public static String url(ModelConfig c)throws Exception{
        switch(c.protocol){case ModelConfig.RESPONSES:return c.base+"/responses";case ModelConfig.CLAUDE:return c.base+"/messages";case ModelConfig.GEMINI:return c.base+"/models/"+URLEncoder.encode(c.model.replaceFirst("^models/",""),"UTF-8")+":streamGenerateContent?alt=sse";case ModelConfig.SIMPLETOOL:return c.base+"/v1/function_call";default:return c.base+"/chat/completions";}
    }
    public static String request(ModelConfig c,String observation,String terrain)throws Exception{
        JSONObject root=new JSONObject();String rules=RULES+"\nITEMS: battle_items contains pickups[kind,x,y], buffs[team,kind,ms], pending_team_kind and epoch/elapsed_ms. Waves never replace remaining pickups: eat ALL current pickups before the next1..6 appear; next_wave_ms=-1 means waiting for clearance. Pickups are solid circular obstacles: full radius8world units, shrinking by HP to minimum2, disappearing only when fully eaten. Phase and teleport cannot enter them; approach the edge to devour. Spawn footprints never cover troops or walls. Pickups have1200 HP: continuous nearby unobstructed devouring is required, globally capped4 HP per7ms step (minimum2.1s); contact is NOT instant use. pickup_kind_x_y_hp_max_leader gives current health. Phase allows walls only: enemy particles remain solid and combat remains active, even at wall edges. Kinds0 grow25% current with50%-initial cap;1 dig20s with25%-initial/500 growth budget;2 freeze20s;3 selected floor teleport;4 once-per-match rewind;5 phase20s;6 invincible20s;7 immediately eliminate every particle of a selected visible enemy;8 selected enemy20s ceasefire, no shared victory and one pact globally. Pending3 uses item_to:[x,y]; pending7/8 uses item_team:0..5. Host uses ONLY that selection; no automatic choice. Counters9..17 match powers0..8: growth seal20s; rock seal20s; thaw/immune20s; teleport anchor20s; causal rewind block20s; expel/block phase20s; shatter/block invincibility20s; death ward20s/one use; end/block ceasefire20s.18 cloak20s hides current locations from enemies,19 reveal20s clears/blocks hostile cloak. Every power spawns with its counter in the same wave; an odd extra is defensive. Hidden enemies are not eliminated; no current hidden positions are provided. Invincibility rejects Death selection and retains the Death card; Ward consumes one Death use and the ward, retaining the target army. Successful Death removes all target troops immediately and grants none to the caster. One-shot growth, teleport, Death and rewind do not repeat for20s. Buff expiry uses simulation time. Changes in epoch or alliance invalidate old commands. SimpleTool may move but cannot select targeted items.\n"+terrain;
        if(c.protocol==ModelConfig.SIMPLETOOL){root.put("system",rules+"\nSIMPLETOOL override: use function move_points only. No route/to/plan fields are supported by this backend. Choose ONE currently visible waypoint yourself using the navigation facts; p1..p5 are simultaneous strings x,y or unused dash, never a waypoint sequence. hold_ms100..2000. All six arguments required.").put("messages",new JSONArray().put(new JSONObject().put("role","user").put("content",observation))).put("max_tokens",32).put("temperature",0).put("include_content_head",false);String raw=root.toString();return raw.substring(0,raw.length()-1)+",\"tools\":"+SIMPLE_TOOLS+"}";}
        if(c.protocol==ModelConfig.GEMINI)return root.put("systemInstruction",new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",rules)))).put("contents",new JSONArray().put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",observation))))).put("generationConfig",new JSONObject().put("maxOutputTokens",2048).put("responseMimeType","application/json")).toString();
        root.put("model",c.model).put("stream",true);
        if(c.protocol==ModelConfig.RESPONSES)return root.put("instructions",rules).put("input",observation).put("max_output_tokens",2048).put("store",false).toString();
        JSONArray messages=new JSONArray();if(c.protocol==ModelConfig.CLAUDE)root.put("system",rules);else messages.put(new JSONObject().put("role","system").put("content",rules));
        root.put("messages",messages.put(new JSONObject().put("role","user").put("content",observation)));String host=new java.net.URI(c.base).getHost();root.put(host.equals("api.openai.com")?"max_completion_tokens":"max_tokens",2048);
        if(host.equals("api.deepseek.com"))root.put("thinking",new JSONObject().put("type","disabled")).put("max_tokens",384).put("temperature",0).put("response_format",new JSONObject().put("type","json_object"));if(host.contains("dashscope")||host.endsWith("maas.aliyuncs.com"))root.put("enable_thinking",false);return root.toString();
    }
    public static ModelAction parse(ModelConfig c,String response)throws Exception{return parse(c,response,800,480);}
    public static ModelAction parse(ModelConfig c,String response,int width,int height)throws Exception{
        JSONObject root=new JSONObject(response);if(c.protocol==ModelConfig.SIMPLETOOL)return ModelAction.simple(root,width,height);String text="";
        if(c.protocol==ModelConfig.GEMINI){JSONObject candidate=root.getJSONArray("candidates").getJSONObject(0);if(!"STOP".equals(candidate.optString("finishReason")))throw new JSONException("Incomplete");JSONArray parts=candidate.getJSONObject("content").getJSONArray("parts");for(int i=0;i<parts.length();i++){JSONObject p=parts.getJSONObject(i);if(!p.optBoolean("thought"))text+=p.optString("text");}}
        else if(c.protocol==ModelConfig.CLAUDE){if(!"end_turn".equals(root.optString("stop_reason")))throw new JSONException("Incomplete");JSONArray parts=root.getJSONArray("content");for(int i=0;i<parts.length();i++){JSONObject p=parts.getJSONObject(i);if("text".equals(p.optString("type")))text+=p.optString("text");}}
        else if(c.protocol==ModelConfig.RESPONSES){if(!"completed".equals(root.optString("status")))throw new JSONException("Incomplete");JSONArray output=root.getJSONArray("output");for(int i=0;i<output.length();i++){JSONObject item=output.getJSONObject(i);if(!"message".equals(item.optString("type")))continue;JSONArray content=item.getJSONArray("content");for(int j=0;j<content.length();j++){JSONObject p=content.getJSONObject(j);if("output_text".equals(p.optString("type")))text+=p.optString("text");}}}
        else{JSONObject choice=root.getJSONArray("choices").getJSONObject(0);if(!"stop".equals(choice.optString("finish_reason")))throw new JSONException("Incomplete");text=choice.getJSONObject("message").getString("content");}
        String object=ModelStream.completeObject(text);if(object==null)throw new JSONException("Incomplete action");return ModelAction.parse(new JSONObject(object),width,height);
    }
}
